def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    if budget <= 0:
        return 0.0

    alive_opponents = []
    prev_bids = []
    urgent_opp = 0
    rich_opp = 0

    for opp_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive_opponents.append(opp)
            if opp.get('budget', 0) > budget:
                rich_opp += 1
            if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 2:
                urgent_opp += 1
            prev = opp.get('previous_trace', {})
            if prev and prev.get('bid') is not None:
                prev_bids.append(prev.get('bid', 0.0))

    if not alive_opponents:
        return float(min(budget, 18.0))

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    tight_supply = supply <= 17
    ample_supply = supply >= 22
    emergency = hp <= 2 or no_water_days >= 2
    danger = hp <= 4 or no_water_days >= 1

    if emergency:
        bid = max(72.0, highest_prev + 4.0)
        if tight_supply:
            bid += 8.0
        return float(min(budget, bid))

    if danger:
        bid = max(46.0, avg_prev + 3.0)
        if highest_prev >= 85.0:
            bid = 52.0
        if tight_supply:
            bid += 8.0
        elif ample_supply:
            bid -= 4.0
        return float(max(0.0, min(budget, bid)))

    if highest_prev >= 95.0:
        bid = 18.0 if ample_supply else 24.0
    elif highest_prev >= 75.0:
        bid = 22.0 if ample_supply else 30.0
    elif highest_prev >= 45.0:
        bid = highest_prev * 0.72
    elif highest_prev > 0.0:
        bid = max(20.0, highest_prev + 1.5)
    else:
        bid = 24.0

    if tight_supply:
        bid += 6.0 + 2.0 * urgent_opp
    elif ample_supply:
        bid -= 4.0

    if rich_opp >= 2 and not ample_supply:
        bid += 3.0

    if day >= 8 and hp >= 7 and no_water_days == 0:
        bid -= 4.0

    bid = max(8.0, bid)
    return float(min(budget, bid))

def get_bid(day_context, my_status, opponents_status):
    DAILY_SALARY = 80
    WATER_REQ = 7
    alive_opponents = [o for o in opponents_status.values() if o['alive']]
    if not alive_opponents:
        return min(my_status['budget'], 10.0)
    yesterday_bids = [o['previous_trace']['bid'] for o in alive_opponents if 'previous_trace' in o and o['previous_trace'].get('bid') is not None]
    if not yesterday_bids:
        return min(my_status['budget'], 45.0)
    max_prev = max(yesterday_bids)
    avg_prev = sum(yesterday_bids) / len(yesterday_bids)
    target = max(avg_prev + 2.0, 40.0)
    if my_status['hp'] < 4:
        target = max(target, max_prev + 5.0)
    return min(my_status['budget'], target)
